// This template is from P5js shader tutorial at
// https://itp-xstory.github.io/p5js-shaders/#/./docs/examples/basic_gradient
let theShader;
let canvas;
let f;
let img;
let textGraphic;

let zoom = 1;

let bx = 0;
let by = 0;
let locked = false;
let xOffset = 0.0;
let yOffset = 0.0;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/1711040/files/vert.glsl', 'frag.glsl');
	f = loadFont("https://openprocessing.org/sketch/1711040/files/RobotoSlab-Light.ttf");
	img = loadImage('https://openprocessing.org/sketch/1711040/files/tile.png');
}

function setup() {
  pixelDensity(2);
  canvas = createCanvas(1000, 1000, WEBGL);
	background(0);

	textGraphic = createGraphics(1000, 1000, WEBGL);
	textGraphic.pixelDensity(2);
	textGraphic.background(0);
	textGraphic.textFont(f);
	textGraphic.textSize(160);
	textGraphic.textAlign(CENTER, CENTER);
	textGraphic.fill("#ffffff");
	textGraphic.text("LOST IN", -5, -200);
	textGraphic.text("THE", 0, -5);
	textGraphic.text("DESERT", -5, 200);
}

function mouseWheel(event) {
  zoom += event.delta * 0.001;
	zoom = max(0.1, zoom);
}

function mousePressed() {
  locked = true;
  xOffset = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - bx;
  yOffset = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - by;
}

function mouseDragged() {
  if (locked) {
    bx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - xOffset;
    by = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - yOffset;
  }
}

function mouseReleased() {
  locked = false;
}

function draw() {
  theShader.setUniform("u_resolution", [width*2, height*2]);
  theShader.setUniform("u_time", millis() / 1000.0);
	theShader.setUniform("u_offset", [-bx, by]);
	theShader.setUniform("u_zoom", zoom);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	theShader.setUniform("u_tile", img);
	theShader.setUniform("u_text", textGraphic);

	noStroke();
	shader(theShader);
  rect(width * -0.5, height * -0.5, width, height);
}

// === Tab: frag.glsl ===
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform vec2 u_mouse;
uniform vec2 u_offset;
uniform float u_zoom;
uniform sampler2D u_tile;
uniform sampler2D u_text;

vec3 rand3(vec3 p) {
	vec3 q = vec3(dot(p, vec3(127.1, 311.7, 74.7)),dot(p, vec3(269.5, 183.3, 246.1)),dot(p, vec3(113.5, 271.9, 124.6)));
	return fract(sin(q) * 43758.5453123);
}

float Checkboard(vec2 uv, float cell_count) {
	vec2 f_uv = fract(uv * cell_count);
	return step(.5, f_uv.x) * step(.5, f_uv.y) + step(-.5, -f_uv.x) * step(-.5, -f_uv.y);
}

float Line(vec2 uv, float cell_count) {
	vec2 f_uv = fract(uv * cell_count);
	return step(.5, f_uv.y);
}

float gray(vec3 color) {
	return 0.299*color.r + 0.587*color.g + 0.114*color.b;
}

float ImgTile(vec2 uv, vec4 sides) {
	sides = step(0.5, sides);
	float tile_index = sides.x + sides.y*2. + sides.z*4. + sides.w*8.;
	vec2 tile_pos = vec2(mod(tile_index, 4.), floor(tile_index / 4.)) / 4.;
	vec2 tile_uv = tile_pos+(uv/4.);
	tile_uv.y = 1. - tile_uv.y;
	float tile_tex = gray(texture2D(u_tile, tile_uv).rgb);

	return tile_tex;
}

float WangTiles(vec2 uv, float cell_count) {
	vec2 gv = fract(uv * cell_count);
	vec2 id = floor(uv * cell_count);

	vec2 r_id = id + vec2(1.,0.);
	vec2 b_id = id + vec2(0.,-1.);

	vec4 sides = vec4(0.);
	sides.x = rand3(vec3(id, 0.)).x;
	sides.y = rand3(vec3(id, 0.)).y;
	sides.z = rand3(vec3(r_id, 0.)).y;
	sides.w = rand3(vec3(b_id, 0.)).x;

	float tile = ImgTile(gv, sides);

	tile += Line(gv, 4.) * 0.1;
	tile -= Line(gv.yx, 4.) * 0.1;
	tile += Line(gv, 8.) * 0.05;
	tile -= Line(gv.yx, 8.) * 0.05;

	return tile;
}

float Wave(float x) {
	float w = sin((x) * 1.) / 1.;
	w += sin((x+153.543) * 1.) / 1.;
	w += sin((x+321.123) * 2.) / 2.;
	w += sin((x+141.111) * 4.) / 4.;
	w += sin((x+233.777) * 8.) / 8.;
	w += sin((x+562.146) * 16.) / 16.;
	w += sin((x+753.543) * 32.) / 32.;
	return w;
}

void main() {
	float c = 0.;
	vec3 col = vec3(0.);
	vec2 uv = gl_FragCoord.xy / u_resolution.xy;
	vec2 screen_uv = uv;
	vec2 mouse = u_mouse / u_resolution.xy;
	mouse = (mouse-.5) * 2.;

	uv += u_offset * 0.001;
	uv *= u_zoom;

	uv -= .5;
	uv *= 0.02;

	uv.x += Wave(uv.y*30.) * .1;
	uv.y += Wave(uv.x*30.) * .03;

	float pattern = 0.;

	//pattern = Checkboard(uv, 30.);
	//pattern = Line(uv, 30.);

	pattern = WangTiles(uv, 30.);

	c = pattern;

	float fog = smoothstep(2., .3, screen_uv.y);
	c *= fog;

	c = smoothstep(0.,1., c);

	float noise = rand3(vec3(uv, 0.)).r;
	c += noise * .2 - .1;
	c = step(.2, c);

	vec2 text_uv = gl_FragCoord.xy / u_resolution.xy;
	text_uv.y = 1.-text_uv.y;
	text_uv.x += Wave((text_uv.y+u_time*.1)*10.) * .002;
	float text = texture2D(u_text, text_uv).r;
	text = step(.5, text);

	c = c + text - 2. * c * text;

  vec3 color1 = vec3(.16, .17, .19);
	vec3 color2 = vec3(.81, .67, .29);

	col = mix(color1, color2, c);

  gl_FragColor = vec4(col,1.0); 
}

// === Tab: vert.glsl ===
 attribute vec3 aPosition;
 attribute vec2 aTexCoord;
 uniform mat4 uProjectionMatrix;
 uniform mat4 uModelViewMatrix;
 varying vec2 vTexCoord;

 void main() {
	 vTexCoord = aTexCoord;
	 vec4 position = vec4(aPosition, 1.0);
	 gl_Position = uProjectionMatrix * uModelViewMatrix * position;
 }

